import sys

class Room:
    def __init__(self, name, description, exits=None, items=None, locked_exits=None):
        self.name = name
        self.description = description
        self.exits = exits or {}  # {direction: Room}
        self.items = items or []  # List of item names
        self.locked_exits = locked_exits or {}  # {direction: required_item}

    def add_exit(self, direction, room, required_item=None):
        self.exits[direction] = room
        if required_item:
            self.locked_exits[direction] = required_item

    def remove_item(self, item_name):
        if item_name in self.items:
            self.items.remove(item_name)
            return True
        return False

    def has_item(self, item_name):
        return item_name in self.items

    def can_exit(self, direction):
        if direction not in self.exits:
            return False
        if direction in self.locked_exits:
            return False
        return True

    def get_room_description(self):
        desc = f"\n{self.name}\n{self.description}"

        # Show items in room
        if self.items:
            desc += f"\nYou see: {', '.join(self.items)}"

        # Show available exits
        available_exits = []
        for direction in self.exits:
            if direction not in self.locked_exits:
                available_exits.append(direction)

        if available_exits:
            desc += f"\nExits: {', '.join(available_exits)}"

        # Show locked exits
        locked_exits = []
        for direction, required_item in self.locked_exits.items():
            locked_exits.append(f"{direction} (requires {required_item})")

        if locked_exits:
            desc += f"\nLocked exits: {', '.join(locked_exits)}"

        return desc

class Player:
    def __init__(self, starting_room):
        self.current_room = starting_room
        self.inventory = []

    def move(self, direction):
        if direction not in self.current_room.exits:
            print("You can't go that way.")
            return False

        # Check if exit is locked
        if direction in self.current_room.locked_exits:
            required_item = self.current_room.locked_exits[direction]
            if required_item not in self.inventory:
                print(f"The {direction} exit is locked. You need a {required_item}.")
                return False
            else:
                print(f"You use the {required_item} to unlock the {direction} exit.")

        self.current_room = self.current_room.exits[direction]
        print(f"You move {direction} to {self.current_room.name}.")
        return True

    def take_item(self, item_name):
        if self.current_room.has_item(item_name):
            self.inventory.append(item_name)
            self.current_room.remove_item(item_name)
            print(f"You take the {item_name}.")
            return True
        else:
            print(f"There is no {item_name} here.")
            return False

    def use_item(self, item_name, target_direction=None):
        if item_name not in self.inventory:
            print(f"You don't have a {item_name}.")
            return False

        # If target_direction is specified, try to unlock that exit
        if target_direction:
            if target_direction in self.current_room.locked_exits:
                required_item = self.current_room.locked_exits[target_direction]
                if item_name == required_item:
                    print(f"You use the {item_name} to unlock the {target_direction} exit!")
                    # Remove the lock
                    del self.current_room.locked_exits[target_direction]
                    return True
                else:
                    print(f"The {item_name} doesn't seem to work for the {target_direction} exit.")
                    return False
            else:
                print(f"There is no locked exit in the {target_direction} direction.")
                return False

        # If no target, just describe using the item
        print(f"You use the {item_name}. Nothing happens.")
        return False

    def show_inventory(self):
        if self.inventory:
            print(f"Inventory: {', '.join(self.inventory)}")
        else:
            print("Your inventory is empty.")

    def show_room(self):
        print(self.current_room.get_room_description())

